"""Flatten Binary Tree to Linked List — Morris-style rewiring.

For each node with a left child, splice that subtree between the node and its
right child by hooking the right child onto the left subtree's rightmost node.

Time: O(n)   Space: O(1)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def flatten(self, root) -> None:
        node = root
        while node:
            if node.left:
                rightmost = node.left
                while rightmost.right:
                    rightmost = rightmost.right
                rightmost.right = node.right
                node.right = node.left
                node.left = None
            node = node.right
